  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Marks all reachable pipe tiles within the specified water-flow distance from the source as filled.
   * Algorithm:
   * 1. If distance is not positive, do nothing.
   * 2. Mark the source cell as filled.
   * 3. Perform breadth-first expansion from the source through connected neighboring pipes.
   * 4. For each expansion layer up to the requested distance:
   *    a. Inspect neighboring cells of already reachable tiles.
   *    b. A neighbor is reachable only when both the current pipe and the neighbor pipe connect through opposite directions.
   *    c. Mark newly reached pipes as filled.
   *    d. Record their coordinates in filledTiles.
   * 5. Preserve previous filled-distance state so only new tiles contribute to incremental growth.
   * Related Features:
   * - filledTiles: stores coordinates of tiles filled by water.
   * - prevFilledDistance: tracks the previous fill radius for incremental updates.
   * - prevFilledTiles: tracks how many tiles were filled before the current update.
   * - sourceCell: starting point for flow.
   * - sinkCell: may be filled if reached by connectivity.
   * - cell: contains map cells and pipes.
   * Related Classes: Coordinate, TerminationCell, FillableCell, Pipe, Direction, Map
   * Input:
   * - distance: non-negative water expansion radius derived from the delay bar.
   * Output: None.
   * Pre-condition:
   * - The map is initialized.
   * - The source cell exists.
   * - The distance value reflects the current water-flow range.
   * Post-condition:
   * - Every reachable pipe tile within the requested distance is marked filled.
   * - The filledTiles collection reflects the newly reached tiles for this update.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance <= 0 || getSourceCell() == null || cell == null)
    {
      return;
    }

    if (filledTiles == null)
    {
      filledTiles = new EObjectContainmentEList<Coordinate>(Coordinate.class, this, Pa19Package.MAP__FILLED_TILES);
    }

    prevFilledTiles = filledTiles.size();
    prevFilledDistance = distance;

    getSourceCell().setFilled(true);

    Set<Coordinate> visited = new HashSet<Coordinate>();
    ArrayDeque<Coordinate> queue = new ArrayDeque<Coordinate>();

    Coordinate start = Pa19Factory.eINSTANCE.createCoordinate();
    start.setRow(getSourceCell().getCoord().getRow());
    start.setCol(getSourceCell().getCoord().getCol());
    visited.add(start);
    queue.add(start);

    int depth = 0;
    while (!queue.isEmpty() && depth < distance)
    {
      int levelSize = queue.size();
      for (int i = 0; i < levelSize; i++)
      {
        Coordinate current = queue.removeFirst();
        Cell currentCell = cell[current.getRow()][current.getCol()];
        if (currentCell == null)
        {
          continue;
        }

        if (currentCell instanceof FillableCell)
        {
          Pipe currentPipe = ((FillableCell)currentCell).getPipe();
          if (currentPipe == null)
          {
            continue;
          }

          for (Direction dir : currentPipe.getConnections())
          {
            int nr = current.getRow();
            int nc = current.getCol();
            switch (dir)
            {
              case UP: nr--; break;
              case DOWN: nr++; break;
              case LEFT: nc--; break;
              case RIGHT: nc++; break;
            }

            if (nr < 0 || nc < 0 || nr >= cell.length || nc >= cell[nr].length)
            {
              continue;
            }

            Cell nextCell = cell[nr][nc];
            if (!(nextCell instanceof FillableCell))
            {
              continue;
            }

            Pipe nextPipe = ((FillableCell)nextCell).getPipe();
            if (nextPipe == null)
            {
              continue;
            }

            boolean connected = false;
            for (Direction nextDir : nextPipe.getConnections())
            {
              if ((dir == Direction.UP && nextDir == Direction.DOWN) ||
                  (dir == Direction.DOWN && nextDir == Direction.UP) ||
                  (dir == Direction.LEFT && nextDir == Direction.RIGHT) ||
                  (dir == Direction.RIGHT && nextDir == Direction.LEFT))
              {
                connected = true;
                break;
              }
            }

            if (connected)
            {
              Coordinate nextCoord = Pa19Factory.eINSTANCE.createCoordinate();
              nextCoord.setRow(nr);
              nextCoord.setCol(nc);
              if (visited.add(nextCoord))
              {
                if (nextCell instanceof TerminationCell)
                {
                  ((TerminationCell)nextCell).setFilled(true);
                }
                else if (nextCell instanceof FillableCell)
                {
                  ((FillableCell)nextCell).getPipe().setFilled(true);
                }
                filledTiles.add(nextCoord);
                queue.add(nextCoord);
              }
            }
          }
        }
      }
      depth++;
    }
  }

